contract InvMutTest {
    C c;
    uint seen;
    bool entered;

    constructor(C _c) { c = _c; }

    function run(uint _put, uint _am) public {
        require(address(this).balance >= _put);
        c.Put{value: _put}(0);
        c.Collect(_am);
        assert(seen == _put - _am);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            (uint _ut, uint _bal) = c.Acc(address(this));
            seen = _bal;
            _ut;
        }
    }

    fallback() external payable {}
}

